import React, { useEffect, useRef } from "react";
import * as THREE from "three";
import { RoundedBoxGeometry } from "three/examples/jsm/geometries/RoundedBoxGeometry.js";
import { RoomEnvironment } from "three/examples/jsm/environments/RoomEnvironment.js";

/* A small live 3D mark beside the Experience title, in place of the 📈
   emoji: three glossy bars rising in the three roles' colours (IIT Delhi
   green → CAMS blue → Think360 violet) with a glowing orb on the tallest.
   It turns slowly, leans toward the pointer, and spins on hover. */

const BARS = [
  { h: 0.9, color: "#00C853" },
  { h: 1.5, color: "#2962FF" },
  { h: 2.2, color: "#8E44AD" },
];

export default function GrowthMark({ size = 96 }) {
  const wrapRef = useRef(null);
  const canvasRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    const wrap = wrapRef.current;
    if (!canvas || !wrap) return undefined;
    let renderer;
    try {
      renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true });
    } catch (e) {
      return undefined;
    }
    const reduce = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    renderer.setSize(size, size, false);
    renderer.outputEncoding = THREE.sRGBEncoding;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 0.85;

    const scene = new THREE.Scene();
    const pmrem = new THREE.PMREMGenerator(renderer);
    const envTex = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;
    scene.environment = envTex;

    const camera = new THREE.PerspectiveCamera(30, 1, 0.1, 50);
    camera.position.set(4.4, 3.2, 6.6);
    camera.lookAt(0, 1.55, 0);

    const key = new THREE.DirectionalLight("#ffffff", 1.1);
    key.position.set(2, 4, 3);
    scene.add(key);

    const group = new THREE.Group();
    scene.add(group);
    const trash = [envTex, pmrem];
    BARS.forEach((b, i) => {
      const geo = new RoundedBoxGeometry(0.62, b.h, 0.62, 4, 0.14);
      const mat = new THREE.MeshPhysicalMaterial({
        // hex colours are sRGB; the renderer outputs sRGB, so convert or
        // every bar comes out pastel
        color: new THREE.Color(b.color).convertSRGBToLinear(),
        metalness: 0.05,
        roughness: 0.28,
        clearcoat: 1,
        clearcoatRoughness: 0.06,
        envMapIntensity: 0.45, // keep the colours saturated, reflections subtle
      });
      const m = new THREE.Mesh(geo, mat);
      m.position.set((i - 1) * 0.78, b.h / 2, (1 - i) * 0.25);
      group.add(m);
      trash.push(geo, mat);
    });
    // glowing orb on the tallest bar
    const orbGeo = new THREE.SphereGeometry(0.2, 32, 32);
    const orbMat = new THREE.MeshStandardMaterial({ color: "#ffffff", emissive: "#c9a0ff", emissiveIntensity: 1.6, roughness: 0.2 });
    const orb = new THREE.Mesh(orbGeo, orbMat);
    group.add(orb);
    trash.push(orbGeo, orbMat);
    const top = BARS[2].h + 0.36;
    orb.position.set(0.78, top, -0.25);
    const light = new THREE.PointLight("#c9a0ff", 1.4, 3);
    orb.add(light);
    // soft contact shadow
    const shGeo = new THREE.CircleGeometry(1.5, 48);
    const shMat = new THREE.MeshBasicMaterial({ color: "#000000", transparent: true, opacity: 0.18 });
    const shadow = new THREE.Mesh(shGeo, shMat);
    shadow.rotation.x = -Math.PI / 2;
    shadow.position.y = -0.01;
    group.add(shadow);
    trash.push(shGeo, shMat);

    // pointer + hover
    let tx = 0;
    let ty = 0;
    let px = 0;
    let py = 0;
    let spin = 0;
    const onMove = (e) => {
      tx = (e.clientX / window.innerWidth) * 2 - 1;
      ty = (e.clientY / window.innerHeight) * 2 - 1;
    };
    const onEnter = () => {
      spin = Math.PI * 2;
    };
    window.addEventListener("pointermove", onMove);
    wrap.addEventListener("pointerenter", onEnter);

    let raf = 0;
    let visible = true;
    let last = performance.now();
    let t = 0;
    let angle = -0.5;
    const tick = (now) => {
      // the first rAF timestamp can precede performance.now(): never step back
      const dt = Math.min(0.05, Math.max(0, (now - last) / 1000));
      last = now;
      t += reduce ? 0 : dt;
      px += (tx - px) * (1 - Math.exp(-dt * 4));
      py += (ty - py) * (1 - Math.exp(-dt * 4));
      // hover spin: one turn, eased out
      const kick = spin * (1 - Math.exp(-dt * 3));
      spin -= kick;
      angle += (reduce ? 0 : dt * 0.35) + kick;
      group.rotation.y = angle + px * 0.35;
      group.rotation.x = py * 0.12;
      orb.position.y = top + Math.sin(t * 2.2) * 0.08;
      orbMat.emissiveIntensity = 1.3 + Math.sin(t * 3) * 0.4;
      renderer.render(scene, camera);
      raf = visible && !document.hidden ? requestAnimationFrame(tick) : 0;
    };
    const start = () => {
      if (!raf && visible && !document.hidden) {
        last = performance.now();
        raf = requestAnimationFrame(tick);
      }
    };
    const io = new IntersectionObserver(([e]) => {
      visible = e.isIntersecting;
      start();
    });
    io.observe(wrap);
    document.addEventListener("visibilitychange", start);
    start();

    return () => {
      cancelAnimationFrame(raf);
      io.disconnect();
      document.removeEventListener("visibilitychange", start);
      window.removeEventListener("pointermove", onMove);
      wrap.removeEventListener("pointerenter", onEnter);
      trash.forEach((d) => d.dispose && d.dispose());
      renderer.dispose();
    };
  }, [size]);

  return (
    <span ref={wrapRef} className="exp-growth-mark" style={{ width: size, height: size }} aria-hidden="true">
      <canvas ref={canvasRef} style={{ width: size, height: size }} />
    </span>
  );
}
