import React, { useCallback, useEffect, useRef, useState } from "react";
import { Link } from "react-router-dom";
import * as THREE from "three";
import { HERO_ROLES, loadImage } from "./roles";

/* ==========================================================
   EXPERIENCE HERO · LOGO PARTICLES
   ~7k glowing particles form each employer's logo in turn, oldest role
   first. Between roles they are pulled into a vortex and re-form as the
   next logo, with a glowing ring and comet orbiting it. A caption names
   the role and what shipped in it (see roles.js). The `figure` (the
   page's illustration) stands in front of the logo.

   Interaction
   - pointer: the scene leans toward it; particles part around it
   - hover the scene: the cycle holds on the current role
   - role dots: jump to a role; the active dot fills as the role plays
   ========================================================== */

const COUNT = 7000;
const HOLD = 4.2; // seconds a logo holds
const MORPH = 1.8; // seconds of vortex between logos
const CYCLE = HOLD + MORPH;
const ORBIT = { rx: 3.9, rz: 2.1, tilt: 0.32, y: -0.1 };

// Sample a logo's ink pixels into COUNT targets (x, y, r, g, b).
function sampleLogo(img, tint, edits = null) {
  const W = 220;
  const s = W / img.width;
  const H = Math.max(1, Math.round(img.height * s));
  const c = document.createElement("canvas");
  c.width = W;
  c.height = H;
  const g = c.getContext("2d", { willReadFrequently: true });
  g.drawImage(img, 0, 0, W, H);
  const rt = edits?.retext;
  if (rt) {
    // swap the wordmark: clear its box, set the new text to the box's cap height
    const [x0, y0, x1, y1] = [rt.box[0] * W, rt.box[1] * H, rt.box[2] * W, rt.box[3] * H];
    g.clearRect(x0, y0, x1 - x0, y1 - y0);
    let size = (y1 - y0) / 0.72;
    g.font = `600 ${size}px "Google Sans Medium", "Google Sans", sans-serif`;
    const tw = g.measureText(rt.text).width;
    if (tw > x1 - x0) {
      size *= (x1 - x0) / tw;
      g.font = `600 ${size}px "Google Sans Medium", "Google Sans", sans-serif`;
    }
    g.fillStyle = rt.color;
    g.textAlign = "center";
    g.textBaseline = "alphabetic";
    g.fillText(rt.text, (x0 + x1) / 2, y1);
  }
  const split = edits?.split && { at: edits.split.at, tint: new THREE.Color(edits.split.color) };
  const d = g.getImageData(0, 0, W, H).data;
  const hits = [];
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      const k = (y * W + x) * 4;
      // keep opaque ink; skip white and pale background (the CAMS logo has a faint grid)
      if (d[k + 3] > 120 && d[k] + d[k + 1] + d[k + 2] < 540) hits.push([x, y, d[k], d[k + 1], d[k + 2]]);
    }
  }
  const out = new Float32Array(COUNT * 5);
  const scale = 5 / W;
  for (let i = 0; i < COUNT; i++) {
    const h = hits.length ? hits[Math.floor(Math.random() * hits.length)] : [W / 2, H / 2, 200, 200, 200];
    out[i * 5] = (h[0] + (Math.random() - 0.5) * 0.8 - W / 2) * scale;
    out[i * 5 + 1] = -(h[1] + (Math.random() - 0.5) * 0.8 - H / 2) * scale + 0.25;
    // the logo's own colour pulled toward the role colour, so dark and
    // grey logos still glow on a dark page
    const mix = (v, t) => Math.min(1, (v / 255) * 0.35 + t * 0.85);
    const c = split && h[0] >= split.at * W ? split.tint : tint;
    out[i * 5 + 2] = mix(h[2], c.r);
    out[i * 5 + 3] = mix(h[3], c.g);
    out[i * 5 + 4] = mix(h[4], c.b);
  }
  return out;
}

function glowSprite() {
  const c = document.createElement("canvas");
  c.width = c.height = 64;
  const g = c.getContext("2d");
  const grd = g.createRadialGradient(32, 32, 0, 32, 32, 32);
  grd.addColorStop(0, "rgba(255,255,255,1)");
  grd.addColorStop(0.25, "rgba(255,255,255,0.5)");
  grd.addColorStop(1, "rgba(255,255,255,0)");
  g.fillStyle = grd;
  g.fillRect(0, 0, 64, 64);
  return new THREE.CanvasTexture(c);
}

// onRoleChange(i) reports the role on screen; controlRef.current.jump(i)
// lets the page's own role stepper drive the scene.
export default function LogoParticles({ light = false, onRoleChange, controlRef, figure = null }) {
  const wrapRef = useRef(null);
  const canvasRef = useRef(null);
  const dotFillRef = useRef(null);
  const [idx, setIdx] = useState(0);
  const ctl = useRef({ jump: -1, hover: false, light });
  ctl.current.light = light;
  const matsRef = useRef(null);

  // Theme: glow (additive) on dark paper; solid, deeper ink on light paper,
  // where additive points would wash out to nothing. Recolours only.
  useEffect(() => {
    const m = matsRef.current;
    if (!m) return;
    const blend = light ? THREE.NormalBlending : THREE.AdditiveBlending;
    [m.mat, m.ringMat, m.dust.material, m.comet.material, m.halo.material].forEach((x) => {
      x.blending = blend;
      x.needsUpdate = true;
    });
    m.mat.uniforms.uDark.value = light ? 1 : 0;
    m.dust.material.color.set(light ? "#6b7280" : "#dfe6ff");
    m.dust.material.opacity = light ? 0.35 : 0.45;
    m.ringMat.opacity = light ? 0.7 : 0.55;
    m.halo.material.opacity = light ? 0.1 : 0.16;
  }, [light]);

  useEffect(() => {
    const canvas = canvasRef.current;
    const wrap = wrapRef.current;
    if (!canvas || !wrap) return undefined;
    let renderer;
    try {
      renderer = new THREE.WebGLRenderer({ canvas, antialias: false, alpha: true });
    } catch (e) {
      return undefined;
    }
    let alive = true;
    const reduce = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(40, 1, 0.1, 100);
    camera.position.set(0, 0.6, 10);
    camera.lookAt(0, 0, 0);
    const world = new THREE.Group();
    scene.add(world);
    const glow = glowSprite();
    const hueCols = HERO_ROLES.map((r) => new THREE.Color(r.color));
    const hue = hueCols[0].clone();

    // ---- logo particles ----
    const pos = new Float32Array(COUNT * 3);
    const col = new Float32Array(COUNT * 3);
    const rnd = new Float32Array(COUNT);
    for (let i = 0; i < COUNT; i++) {
      rnd[i] = Math.random();
      const a = Math.random() * Math.PI * 2;
      const r = 2 + Math.random() * 5;
      pos.set([Math.cos(a) * r, (Math.random() - 0.5) * 5, Math.sin(a) * r], i * 3);
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute("position", new THREE.BufferAttribute(pos, 3));
    geo.setAttribute("color", new THREE.BufferAttribute(col, 3));
    geo.setAttribute("aRnd", new THREE.BufferAttribute(rnd, 1));
    const mat = new THREE.ShaderMaterial({
      uniforms: {
        uSize: { value: 22 * renderer.getPixelRatio() },
        uTime: { value: 0 },
        uDark: { value: 0 },
      },
      vertexShader: `
        attribute float aRnd; varying vec3 vC; uniform float uSize; uniform float uTime;
        void main(){ vC = color; vec4 mv = modelViewMatrix*vec4(position,1.);
          gl_Position = projectionMatrix*mv;
          gl_PointSize = uSize*(0.55+aRnd*0.7)*(0.85+0.15*sin(uTime*2.+aRnd*30.))/-mv.z; }`,
      fragmentShader: `
        varying vec3 vC; uniform float uDark;
        void main(){ float d = length(gl_PointCoord-.5); if(d>.5) discard;
          float a = smoothstep(.5,0.,d);
          // light paper: deepen the colour and give the dot a solid core
          vec3 c = mix(vC, vC*0.62, uDark);
          a = mix(a, smoothstep(.5,.2,d)*0.9, uDark);
          gl_FragColor = vec4(c, a); }`,
      vertexColors: true,
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
    });
    world.add(new THREE.Points(geo, mat));

    // ---- orbit ring: a thin band of light round the logo ----
    const orbit = new THREE.Group();
    orbit.rotation.x = ORBIT.tilt;
    orbit.position.y = ORBIT.y;
    world.add(orbit);
    const RING = 900;
    const rp = new Float32Array(RING * 3);
    for (let i = 0; i < RING; i++) {
      const a = (i / RING) * Math.PI * 2;
      const j = (Math.random() - 0.5) * 0.08;
      rp.set([Math.cos(a) * (ORBIT.rx + j), (Math.random() - 0.5) * 0.05, Math.sin(a) * (ORBIT.rz + j)], i * 3);
    }
    const ringGeo = new THREE.BufferGeometry();
    ringGeo.setAttribute("position", new THREE.BufferAttribute(rp, 3));
    const ringMat = new THREE.PointsMaterial({
      size: 0.05,
      map: glow,
      color: hue,
      transparent: true,
      opacity: 0.55,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
    });
    const ring = new THREE.Points(ringGeo, ringMat);
    orbit.add(ring);
    // a comet running round the ring
    const comet = new THREE.Sprite(
      new THREE.SpriteMaterial({ map: glow, color: hue, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false })
    );
    comet.scale.setScalar(0.55);
    orbit.add(comet);

    // ---- ambient dust ----
    const D = 700;
    const dp = new Float32Array(D * 3);
    for (let i = 0; i < D; i++) dp.set([(Math.random() - 0.5) * 16, (Math.random() - 0.5) * 10, (Math.random() - 0.5) * 8 - 2], i * 3);
    const dustGeo = new THREE.BufferGeometry();
    dustGeo.setAttribute("position", new THREE.BufferAttribute(dp, 3));
    const dust = new THREE.Points(
      dustGeo,
      new THREE.PointsMaterial({ size: 0.035, map: glow, color: 0xdfe6ff, transparent: true, opacity: 0.45, depthWrite: false, blending: THREE.AdditiveBlending })
    );
    scene.add(dust);

    // ---- soft halo behind the logo ----
    const halo = new THREE.Sprite(
      new THREE.SpriteMaterial({ map: glow, color: hue, transparent: true, opacity: 0.16, blending: THREE.AdditiveBlending, depthWrite: false })
    );
    halo.scale.set(9, 5, 1);
    halo.position.z = -1.5;
    world.add(halo);

    matsRef.current = { mat, ringMat, dust, comet, halo };
    // apply the current theme to the freshly built materials
    {
      const lt = ctl.current.light;
      const blend = lt ? THREE.NormalBlending : THREE.AdditiveBlending;
      [mat, ringMat, dust.material, comet.material, halo.material].forEach((x) => {
        x.blending = blend;
      });
      mat.uniforms.uDark.value = lt ? 1 : 0;
      dust.material.color.set(lt ? "#6b7280" : "#dfe6ff");
      ringMat.opacity = lt ? 0.7 : 0.55;
      halo.material.opacity = lt ? 0.1 : 0.16;
    }

    // ---- sizing ----
    const resize = () => {
      const w = wrap.clientWidth;
      const h = wrap.clientHeight;
      if (!w || !h) return;
      renderer.setSize(w, h, false);
      camera.aspect = w / h;
      camera.position.z = w / h < 1 ? 13 : 10;
      camera.updateProjectionMatrix();
    };
    resize();
    let rz = 0;
    const ro = new ResizeObserver(() => {
      cancelAnimationFrame(rz);
      rz = requestAnimationFrame(resize);
    });
    ro.observe(wrap);

    // ---- pointer ----
    const hand = new THREE.Vector3(99, 99, 0);
    const tilt = { x: 0, y: 0, tx: 0, ty: 0 };
    const tmpV = new THREE.Vector3();
    const onMove = (e) => {
      const r = canvas.getBoundingClientRect();
      const nx = ((e.clientX - r.left) / r.width) * 2 - 1;
      const ny = -((e.clientY - r.top) / r.height) * 2 + 1;
      tmpV.set(nx, ny, 0.5).unproject(camera).sub(camera.position).normalize();
      hand.copy(camera.position).addScaledVector(tmpV, -camera.position.z / tmpV.z);
      tilt.tx = (e.clientX / window.innerWidth) * 2 - 1;
      tilt.ty = (e.clientY / window.innerHeight) * 2 - 1;
    };
    const onEnter = () => {
      ctl.current.hover = true;
    };
    const onLeave = () => {
      hand.set(99, 99, 0);
      ctl.current.hover = false;
    };
    window.addEventListener("pointermove", onMove);
    wrap.addEventListener("pointerenter", onEnter);
    wrap.addEventListener("pointerleave", onLeave);

    let targets = null;
    Promise.all(HERO_ROLES.map((r) => loadImage(r.logo))).then((imgs) => {
      if (!alive) return;
      targets = imgs.map((img, i) => (img ? sampleLogo(img, hueCols[i], HERO_ROLES[i].edits) : null));
    });

    // ---- loop ----
    let raf = 0;
    let visible = true;
    let last = performance.now();
    let t = 0; // animation clock
    let cyc = 0; // role-cycle clock (holds while hovered)
    let spin = 0; // orbit angle
    let shown = -1;

    const tick = (now) => {
      // the first rAF timestamp can precede performance.now(): never step back
      const dt = Math.min(0.05, Math.max(0, (now - last) / 1000));
      last = now;
      t += dt;
      mat.uniforms.uTime.value = t;
      const n = HERO_ROLES.length;

      // role cycle: a dot click jumps; hovering holds on the current logo
      if (ctl.current.jump >= 0) {
        cyc = ctl.current.jump * CYCLE + 0.01;
        ctl.current.jump = -1;
      }
      const inHold = cyc % CYCLE < HOLD;
      if (!(ctl.current.hover && inHold) && !reduce) cyc += dt;
      const k = Math.floor(cyc / CYCLE) % n;
      const phase = cyc % CYCLE;
      if (k !== shown) {
        shown = k;
        setIdx(k);
      }
      if (dotFillRef.current) dotFillRef.current.style.transform = `scaleX(${Math.min(1, phase / CYCLE)})`;
      hue.lerp(hueCols[k], 1 - Math.exp(-dt * 3));
      ringMat.color.copy(hue);
      comet.material.color.copy(hue);
      halo.material.color.copy(hue);

      tilt.x += (tilt.tx - tilt.x) * (1 - Math.exp(-dt * 3));
      tilt.y += (tilt.ty - tilt.y) * (1 - Math.exp(-dt * 3));
      world.rotation.y = tilt.x * 0.3 + Math.sin(t * 0.35) * 0.07;
      world.rotation.x = tilt.y * 0.12;
      dust.rotation.y = t * 0.01;

      // particles
      if (targets) {
        const tgt = targets[k] || targets.find(Boolean);
        const burst = phase > HOLD ? Math.sin(((phase - HOLD) / MORPH) * Math.PI) : 0;
        const pull = 1 - Math.exp(-dt * (phase > HOLD ? 3 : 6));
        for (let i = 0; i < COUNT; i++) {
          const i3 = i * 3;
          const i5 = i * 5;
          const r = rnd[i];
          let tx = tgt[i5];
          let ty = tgt[i5 + 1];
          let tz = Math.sin(t * 1.3 + r * 20) * 0.06;
          if (burst > 0) {
            // vortex: swing each point round the centre and out onto a disc
            const a = Math.atan2(ty, tx) + burst * (2.2 + r * 2.5);
            const rr = Math.hypot(tx, ty) * (1 + burst * 0.5) + burst * (0.8 + r * 2.6);
            tx = Math.cos(a) * rr;
            ty = Math.sin(a) * rr * 0.55;
            tz += (r - 0.5) * burst * 3;
          }
          let x = pos[i3] + (tx - pos[i3]) * pull;
          let y = pos[i3 + 1] + (ty - pos[i3 + 1]) * pull;
          const z = pos[i3 + 2] + (tz - pos[i3 + 2]) * pull;
          const dx = x - hand.x;
          const dy = y - hand.y;
          const d2 = dx * dx + dy * dy;
          if (d2 < 1.3) {
            const f = (1.3 - d2) * 0.14;
            x += dx * f;
            y += dy * f;
          }
          pos[i3] = x;
          pos[i3 + 1] = y;
          pos[i3 + 2] = z;
          col[i3] += (tgt[i5 + 2] - col[i3]) * pull;
          col[i3 + 1] += (tgt[i5 + 3] - col[i3 + 1]) * pull;
          col[i3 + 2] += (tgt[i5 + 4] - col[i3 + 2]) * pull;
        }
        geo.attributes.position.needsUpdate = true;
        geo.attributes.color.needsUpdate = true;
      }

      // orbit
      spin += dt * (reduce ? 0 : 0.22);
      ring.rotation.y = -spin * 0.5;
      const ca = t * 0.9;
      comet.position.set(Math.cos(ca) * ORBIT.rx, 0, Math.sin(ca) * ORBIT.rz);

      renderer.render(scene, camera);
      raf = visible && !document.hidden ? requestAnimationFrame(tick) : 0;
    };
    const start = () => {
      if (!raf && visible && !document.hidden) {
        last = performance.now();
        raf = requestAnimationFrame(tick);
      }
    };
    const io = new IntersectionObserver(([e]) => {
      visible = e.isIntersecting;
      start();
    });
    io.observe(wrap);
    document.addEventListener("visibilitychange", start);
    start();

    return () => {
      alive = false;
      cancelAnimationFrame(raf);
      cancelAnimationFrame(rz);
      io.disconnect();
      ro.disconnect();
      document.removeEventListener("visibilitychange", start);
      window.removeEventListener("pointermove", onMove);
      wrap.removeEventListener("pointerenter", onEnter);
      wrap.removeEventListener("pointerleave", onLeave);
      [geo, mat, ringGeo, ringMat, dustGeo, dust.material, glow, comet.material, halo.material].forEach((d) => d.dispose());
      renderer.dispose();
    };
  }, []);

  const jump = useCallback((i) => {
    ctl.current.jump = i;
  }, []);
  useEffect(() => {
    if (controlRef) controlRef.current = { jump };
  }, [controlRef, jump]);
  const roleCb = useRef(onRoleChange);
  roleCb.current = onRoleChange;
  useEffect(() => {
    roleCb.current?.(idx);
  }, [idx]);

  const role = HERO_ROLES[idx];
  return (
    <div ref={wrapRef} className="xh xh-particles" style={{ "--c": role ? role.color : "#2962FF" }}>
      <canvas ref={canvasRef} aria-hidden="true" />
      {figure && <div className="xh-figure">{figure}</div>}

      {role && (
        <div key={`c${idx}`} className="xh-caption is-on is-auto">
          <span>
            <b>{role.title}</b> · {role.company} · {role.duration}
          </span>
          {role.shipped?.length > 0 && (
            <span className="xh-shipped">
              Shipped:{" "}
              {role.shipped.map((p, i) => (
                <React.Fragment key={p.slug}>
                  {i > 0 && " · "}
                  <Link to={`/projects/${p.slug}`}>{p.name}</Link>
                </React.Fragment>
              ))}
            </span>
          )}
        </div>
      )}
      <ol className="xh-dots">
        {HERO_ROLES.map((r, i) => (
          <li key={r.company}>
            <button
              type="button"
              className={i === idx ? "is-on" : ""}
              style={{ "--c": r.color }}
              onClick={() => jump(i)}
              aria-label={`${r.title}, ${r.company}`}
            >
              {i === idx && <i ref={dotFillRef} />}
            </button>
          </li>
        ))}
      </ol>
    </div>
  );
}
